<?php $title='Platform tenants'; ?>
<section class="page-header"><div><span class="eyebrow">Platform</span><h1>Tenants</h1><p>Manage organizations, domains and access.</p></div><a class="btn btn-primary" href="<?=e(url('platform/tenants/create'))?>">Create organization</a></section>
<?php if(!empty($error)):?><div class="alert alert-danger"><?=e($error)?></div><?php endif?>
<section class="content-card"><div class="table-wrap"><table class="data-table"><thead><tr><th>Organization</th><th>Slug</th><th>Status</th><th>Domains</th><th>Created</th><th>Actions</th></tr></thead><tbody>
<?php if(empty($tenants)):?><tr><td colspan="6" class="muted">No organizations have been created yet.</td></tr><?php endif?>
<?php foreach($tenants as $tenant):?><tr><td><?=e($tenant['name'])?></td><td><?=e($tenant['slug'])?></td><td><?=e($tenant['status'])?></td><td><?=count($tenant['domains']??[])?></td><td><?=e((string)$tenant['created_at'])?></td><td><div class="inline-actions"><a class="btn btn-secondary" href="<?=e(url('platform/tenant-view?id='.(int)$tenant['id']))?>">View</a><a class="btn btn-secondary" href="<?=e(url('platform/tenant-edit?id='.(int)$tenant['id']))?>">Edit</a><a class="btn btn-secondary" href="<?=e(url('platform/tenant-database?id='.(int)$tenant['id']))?>">Database</a><form method="post"><input type="hidden" name="_csrf" value="<?=e(Csrf::token())?>"><input type="hidden" name="id" value="<?= (int)$tenant['id']?>"><?php if($tenant['status']==='active'):?><input type="hidden" name="status" value="suspended"><button class="btn btn-secondary" data-confirm="Suspend this tenant?">Suspend</button><?php else:?><input type="hidden" name="status" value="active"><button class="btn btn-primary" data-confirm="Activate this tenant?">Activate</button><?php endif?></form></div></td></tr><?php endforeach?></tbody></table></div></section>